def transform(grid):
    h, w = len(grid), len(grid[0])
    marked = set()

    for r in range(h):
        if len(set(grid[r])) == 1:
            marked.update((r, c) for c in range(w))

    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            marked.update((r, c) for r in range(h))

    return [[2 if (r, c) in marked else grid[r][c]
             for c in range(w)] for r in range(h)]
